#!/usr/bin/env python3
"""Install the corrected UART test on Jetson. No FPGA or OS settings are changed.
Usage: python3 install_igor_uart.py [path-to-igor_ws]
"""
import base64
import hashlib
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile

PAYLOAD = ''
SHA256 = 'cdec7d81cd3f6ad90857ac7ec61bf16b810bc623f7cf6b8b2621c276d98fb05d'

def main():
    root = Path(sys.argv[1]).expanduser().resolve() if len(sys.argv) > 1 else Path.home() / 'igor_ws'
    target = root / 'src/igor_pipeline/scripts/uart_test.py'
    if not target.parent.is_dir():
        raise SystemExit(f'Workspace not found: {root}. Pass its path as the first argument.')
    try:
        import serial
    except ImportError:
        raise SystemExit('Install pyserial first: python3 -m pip install --user pyserial')
    content = base64.b64decode(PAYLOAD)
    if hashlib.sha256(content).hexdigest() != SHA256:
        raise SystemExit('Installer payload checksum failed')
    compile(content, str(target), 'exec')
    backup = None
    if target.exists():
        old_hash = hashlib.sha256(target.read_bytes()).hexdigest()
        if old_hash != SHA256:
            backup = target.with_name('uart_test.py.backup-' + old_hash[:12])
            if not backup.exists():
                shutil.copy2(target, backup)
    with tempfile.NamedTemporaryFile(dir=target.parent, suffix='.py', delete=False) as f:
        temporary = Path(f.name)
        f.write(content)
    try:
        subprocess.run([sys.executable, str(temporary), '--self-check'], check=True)
        if target.exists():
            shutil.copymode(target, temporary)
        temporary.replace(target)
    finally:
        temporary.unlink(missing_ok=True)
    print(f'Installed: {target}\nSHA256: {SHA256}')
    if backup:
        print(f'Previous script saved: {backup}')
    subprocess.run([sys.executable, str(target), '--self-check'], check=True)
    print(f'Next: python3 {target} --port /dev/ttyTHS1 --baud 921600 --iter 50')

if __name__ == '__main__':
    main()
